$('saveTerrain').onclick=()=>{const value={format:'leaf-terrain',version:1,extent:map.extent,terrain:map.terrain,terrainTiles:map.terrainTiles};const url=URL.createObjectURL(new Blob([JSON.stringify(value)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='leaf-terrain.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Terrain exported separately.');};
$('loadTerrain').onclick=()=>$('terrainFile').click();$('terrainFile').onchange=async()=>{try{const f=$('terrainFile').files[0];if(!f)return;if(f.size>200000000)throw Error('Terrain file exceeds 200 MB.');const value=JSON.parse(await f.text());if(value.format!=='leaf-terrain'||value.version!==1)throw Error('Unsupported terrain format.');const next=structuredClone(map);if(value.extent!==map.extent)throw Error('Terrain dimensions must match this map. Create a new map with the required size first.');next.terrain=value.terrain;next.terrainTiles=value.terrainTiles??{};validateMap(next);commit(next);fit();toast('Terrain loaded; existing objects are attached to the new surface.');}catch(e){toast('Could not load terrain: '+e.message);}finally{$('terrainFile').value='';}};

$('radiusNumber').onchange=()=>{$('radius').value=Math.max(.5,Math.min(256,Number($('radiusNumber').value)||2));$('radius').oninput();};

const animeDescriptions={painted:'Soft painted colour clusters with warm light and cool shadows.',cel:'Clean light bands, saturated colour and strong silhouette ink.',watercolour:'Pale colour washes, paper pigment and broken ink contours.'};
function refreshAnimeControls(){const off=view.anime===false,cel=$('animeMode').value==='cel';$('animeMode').disabled=off;$('colourSoftness').disabled=off||cel;$('paintTexture').disabled=off||cel;$('outlineStrength').disabled=off;}
$('animeMode').onchange=()=>{view.animeMode=$('animeMode').value;refreshAnimeControls();$('animeModeDescription').textContent=animeDescriptions[view.animeMode];request();};
$('waterWaveStrength').oninput=()=>{view.waterWaveStrength=Number($('waterWaveStrength').value);request();};
$('waterReflections').onchange=()=>{view.waterReflections=$('waterReflections').checked;request();};
$('castShadows').onchange=()=>{view.shadows=$('castShadows').checked;$('shadowStrength').disabled=!view.shadows;request();};
$('shadowStrength').oninput=()=>{view.shadowStrength=Number($('shadowStrength').value);request();};
$('animeStyle').onchange=()=>{view.anime=$('animeStyle').checked;refreshAnimeControls();request();};
$('outlineStrength').oninput=()=>{view.outline=Number($('outlineStrength').value);request();};

$('colourSoftness').oninput=()=>{view.softness=Number($('colourSoftness').value);request();};

$('paintTexture').oninput=()=>{view.paint=Number($('paintTexture').value);request();};

$('groundCover').onchange=()=>{view.groundCover=$('groundCover').checked;request();};
